interface RftTransform {
  position: { x: number; y: number; z: number; set(x:number,y:number,z:number):void };
  rotation: { x: number; y: number; z: number; set(x:number,y:number,z:number):void };
  scale: { x: number; y: number; z: number; set(x:number,y:number,z:number):void };
  lookAt(x: number, y: number, z: number): void;
}
interface RftInput {
  isKeyDown(code: string): boolean;
  isKeyPressed(code: string): boolean;
  isActionActive(action: string): boolean;
  isActionPressed(action: string): boolean;
  isActionReleased(action: string): boolean;
  axis(neg: string, pos: string): number;
  mouse: { x:number; y:number; dx:number; dy:number; buttons:number };
  wheel: number;
}
interface RftPhysics {
  applyImpulse(entity: any, x: number, y: number, z: number): void;
  setVelocity(entity: any, x: number, y: number, z: number): void;
  getVelocity(entity: any): any;
  teleport(entity: any, x: number, y: number, z: number): void;
  isGrounded(entity: any, distance?: number): boolean;
  raycast(origin: any, direction: any, maxDistance?: number): { acertou: boolean; objeto: any; distancia: number };
}
interface RftGame {
  getNumber(key: string): number;
  setNumber(key: string, value: number): void;
  add(key: string, delta: number): number;
  getFlag(key: string): boolean;
  setFlag(key: string, value: boolean): void;
}
interface RftHud {
  bar(id: string, o: { label: string; value: number; max: number; color?: string }): void;
  counter(id: string, o: { label: string; value: number; icon?: string }): void;
  tracker(id: string, o: { label: string; value: number; max: number; done?: boolean }): void;
  dialogue(text: string, choices: string[], onPick: (i: number) => void): void;
  hideDialogue(): void;
  showBanner(title: string, sub?: string): void;
  hideBanner(): void;
}
interface RftTime { delta: number; elapsed: number; frame: number; timescale: number; }
interface RftPathSampler { usable: boolean; localAt(u:number,out?:any):any; localTangent(u:number,out?:any):any; worldAt(u:number,anchor:any,out?:any):any; worldTangent(u:number,anchor:any,out?:any):any; }
interface RftEntity { name: string; active: boolean; id: string; object3D: any; }

declare abstract class Behaviour {
  entity: RftEntity;
  enabled: boolean;
  readonly transform: RftTransform;
  readonly input: RftInput;
  readonly physics: RftPhysics;
  readonly game: RftGame;
  readonly hud: RftHud | null;
  readonly time: RftTime;
  readonly scene: any;
  spawnPrefab(name: string, x?: number, y?: number, z?: number): RftEntity | null;
  damage(target: RftEntity | null, amount: number): void;
  tone(freq?: number, dur?: number, vol?: number, type?: string): void;
  aimAt(x: number, y: number, z: number): void;
  viewDirOf(entity: RftEntity | null): any;
  captureMatrix(): any;
  pathAnchor(space: string, anchorName?: string, spawn?: any): any;
  pathPoint(sampler: RftPathSampler, u: number, space: string, anchorName?: string, spawn?: any): any;
  pathTangent(sampler: RftPathSampler, u: number, space: string, anchorName?: string, spawn?: any): any;
  hitstop(seconds?: number, scale?: number): void;
  shakeCamera(amount?: number, seconds?: number): void;
  perceives(target: RftEntity | null, range?: number, angleDeg?: number, los?: boolean): boolean;
  separationForce(name: string, radius?: number): any;
  showDialogue(text: string, choices: string[], onPick: (i: number) => void): void;
  saveGame(slot?: string | number): void;
  loadGame(slot?: string | number): boolean;
  onDamage?(amount: number, from: RftEntity): void;
  readonly playing: boolean;
  log(...args: any[]): void;
  warn(...args: any[]): void;
  error(...args: any[]): void;
  find(name: string): RftEntity | null;
  getComponent<T = any>(type: string): T | undefined;
  destroy(): void;
  spawn(name?: string): RftEntity;
  loadScene(name: string): void;
  onCollision?(other: RftEntity): void;
  onTrigger?(other: RftEntity): void;
  start(): void;
  update(dt: number): void;
  fixedUpdate(dt: number): void;
  onDestroy(): void;
}
